#!/usr/bin/env node
// Imports the reviews of an old CR pack into a crharness. Idempotent and non-destructive.
// Usage: node scripts/import-pack.js <pack-dir> <area-dir> [--dry-run]
// - New PR folders are copied whole.
// - Existing PR folders are merged file by file: missing files are copied, identical ones skipped,
//   different ones are reported as conflicts and never overwritten.
// - STATUS.md and PACK.md are generated by the skill and are not imported (regenerate the index afterwards).
// - Rows of the pack's reviews/INPUT.md are appended to the area's, deduplicated by PR.

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const args = process.argv.slice(2);
const dryRun = args.includes('--dry-run');
const [packArg, areaArg] = args.filter((a) => !a.startsWith('--'));
if (!packArg || !areaArg) {
  console.error('Usage: node scripts/import-pack.js <pack-dir> <area-dir> [--dry-run]');
  process.exit(1);
}

const packReviews = path.join(path.resolve(packArg), 'reviews');
const areaReviews = path.join(path.resolve(areaArg), 'reviews');
for (const dir of [packReviews, areaReviews]) {
  if (!fs.existsSync(dir)) {
    console.error(`Not found: ${dir}`);
    process.exit(1);
  }
}

const GENERATED = new Set(['STATUS.md']);
const hash = (file) => crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
const report = { copied: [], identical: 0, conflicts: [], skipped: [], rows: 0 };

function walk(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const full = path.join(dir, e.name);
    return e.isDirectory() ? walk(full) : [full];
  });
}

function importPr(name) {
  const src = path.join(packReviews, name);
  const dest = path.join(areaReviews, name);
  if (fs.existsSync(path.join(areaReviews, '_archive', name))) {
    report.skipped.push(`${name} (already archived in the area)`);
    return;
  }
  if (!fs.existsSync(dest)) {
    report.copied.push(`${name}/ (whole folder)`);
    if (!dryRun) fs.cpSync(src, dest, { recursive: true, filter: (s) => !GENERATED.has(path.basename(s)) });
    return;
  }
  for (const file of walk(src)) {
    const rel = path.relative(src, file);
    if (GENERATED.has(path.basename(rel))) continue;
    const target = path.join(dest, rel);
    if (!fs.existsSync(target)) {
      report.copied.push(`${name}/${rel}`);
      if (!dryRun) {
        fs.mkdirSync(path.dirname(target), { recursive: true });
        fs.copyFileSync(file, target);
      }
    } else if (hash(file) === hash(target)) {
      report.identical++;
    } else {
      report.conflicts.push(`${name}/${rel}`);
    }
  }
}

for (const e of fs.readdirSync(packReviews, { withFileTypes: true })) {
  if (e.isDirectory() && /-PR\d+$/.test(e.name)) importPr(e.name);
}

// INPUT.md rows
const prKey = (cell) => {
  const m = cell.match(/github\.com\/([^/\s]+)\/([^/\s]+)\/pull\/(\d+)/i);
  return m ? `${m[1]}/${m[2]}/${m[3]}`.toLowerCase() : null;
};
const parseRows = (text) =>
  text
    .split(/\r?\n/)
    .filter((l) => l.trim().startsWith('|'))
    .map((l) => l.trim().replace(/^\||\|$/g, '').split('|').map((c) => c.trim()))
    .filter((cells) => cells.length >= 2 && prKey(cells[0]));

const packInput = path.join(packReviews, 'INPUT.md');
const areaInput = path.join(areaReviews, 'INPUT.md');
if (fs.existsSync(packInput)) {
  const existing = fs.existsSync(areaInput) ? fs.readFileSync(areaInput, 'utf8') : null;
  const known = new Set(existing ? parseRows(existing).map((c) => prKey(c[0])) : []);
  const urlOf = (cell) => (cell.match(/https?:\/\/[^\s)\]"]+/) || [cell])[0].replace(/\/$/, '');
  const fresh = parseRows(fs.readFileSync(packInput, 'utf8')).filter((c) => {
    const k = prKey(c[0]);
    if (known.has(k)) return false;
    known.add(k);
    return true;
  });
  report.rows = fresh.length;
  if (!dryRun && fresh.length) {
    const lines = fresh.map((c) => `| ${urlOf(c[0])} | ${urlOf(c[1] || '')} | ${(c[2] || '').replace(/\|/g, '/')} |`);
    const header =
      existing ??
      '# Fila de PRs\n\nUma linha por PR. Jira pode ser a chave (`ABC-123`) ou a URL. A nota é opcional.\n\n| PR | Jira | Nota |\n|---|---|---|\n';
    fs.writeFileSync(areaInput, header.replace(/\s*$/, '\n') + lines.join('\n') + '\n');
  }
}

console.log(`${dryRun ? '[dry-run] ' : ''}Import ${packArg} -> ${areaArg}`);
console.log(`Copied (${report.copied.length}):`);
report.copied.forEach((c) => console.log(`  + ${c}`));
console.log(`Identical, skipped: ${report.identical}`);
console.log(`Conflicts, NOT overwritten (${report.conflicts.length}):`);
report.conflicts.forEach((c) => console.log(`  ! ${c}`));
if (report.skipped.length) report.skipped.forEach((s) => console.log(`Skipped: ${s}`));
console.log(`INPUT rows added: ${report.rows}`);
console.log('Next: ask the skill to regenerate the index (PACK.md and STATUS.md).');
